  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const NoteDetail = Note.extend({ archived: z.boolean() })

