  input: z.object({ number: z.string() }),
  output: NoteDetail,
  errors: { Unauthorized: z.object({}), NotFound: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
  output: z.object({ ids: z.array(z.string()) }),
  errors: { ...IsReadOnly },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const sharedNotes = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const UserNotes = z.object({ name: z.string(), notes: z.number().int(), readOnly: z.boolean(), admin: z.boolean() })

export const adminUsers = query({
  input: z.object({}),
  output: z.array(UserNotes),
  errors: { Unauthorized: z.object({}), Forbidden: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const shareNote = mutation({
  input: NoteKey.extend({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') }),
  output: Note,
  errors: { Self: z.object({}), NotFound: NoteKey, ...IsArchived, ...IsReadOnly },
  invalidates: () => [notesTag()],
  runs: 'server',
})

